dict(n=23, sess="L30", sim="appdepth", tn=["TN8", "TN9", "TN13", "TN15"], refs=[3, 4, "Q6"], intl=["hecht", "pedrotti"],
 title=r"Mikroskop yordamida shishaning sindirish ko‘rsatkichini aniqlash",
 short=r"Mikroskop usulida sindirish ko‘rsatkichi",
 goal=r"Shisha plastinaning haqiqiy qalinligini va mikroskop orqali ko‘rinadigan (zohiriy) qalinligini o‘lchab, sindirish ko‘rsatkichini aniqlash; usul aniqligining obyektiv aperturasiga bog‘liqligini tahlil qilish.",
 equip=["Mikrometr vintli (fokuslash shkalali) mikroskop", "Ikki tomonida chiziq (shtrix) belgilangan shisha plastina", "Mikrometr yoki shtangensirkul", "Yoritgich"],
 theory=[
  ("Zohiriy chuqurlik", r"<p>Shisha ostidagi nuqtadan chiqqan nurlar sirtda sinib, ko‘zga go‘yo yuqoriroqdagi nuqtadan chiqqandek ko‘rinadi. Paraksial nurlar uchun zohiriy qalinlik</p>$$h=\frac dn\quad\Rightarrow\quad n=\frac dh.$$"),
  ("Mikroskopda o‘lchash", r"<p>Mikroskop avval plastina ustidagi shtrixga, so‘ng ostidagi shtrixga (plastina orqali) fokuslanadi. Tubus siljishi zohiriy qalinlik \(h\) ga teng. Haqiqiy qalinlik \(d\) mikrometr bilan o‘lchanadi.</p>"),
  ("Aniqlik chegarasi", r"<p>Fokuslash aniqligi mikroskopning maydon chuqurligi bilan cheklanadi: \(\Delta z\approx\lambda/\mathrm{NA}^2\). Katta aperturali obyektivda aniqlik yuqori, lekin chekka nurlar paraksial yaqinlashuvdan chiqadi (sferik aberratsiya).</p>")],
 proc=["Plastina qalinligini mikrometr bilan 5 joyda o‘lchang.", "Mikroskopni plastinaning yuqori shtrixiga aniq fokuslang; mikrometr vint ko‘rsatishini yozing.", "Tubusni pastga siljitib, pastki shtrixga (shisha orqali) fokuslang; ko‘rsatishni yozing.", "Har ikki fokuslashni 5 marta takrorlang (vintni bir yo‘nalishda aylantiring — lyuftni yo‘qotish uchun).", r"\(h\) o‘rtachasini topib, \(n=d/h\) ni hisoblang.", "Boshqa plastina (yoki suv qatlami) uchun takrorlang."],
 tbl=(["№", "d, mm", "z₁, mm", "z₂, mm", "h = |z₁ − z₂|, mm"], 5),
 calc=r"<p>\(n=\bar d/\bar h\), \(\dfrac{\Delta n}{n}=\dfrac{\Delta d}{d}+\dfrac{\Delta h}{h}\). Odatda \(\Delta h\) (fokuslash) ustun bo‘ladi.</p>",
 example=(r"\(d=3{,}00\pm0{,}01\) mm, zohiriy qalinlik \(h=1{,}98\pm0{,}02\) mm. \(n\) va xatolikni toping.",
  r"\(n=3{,}00/1{,}98=1{,}52\). \(\delta=0{,}0033+0{,}0101=0{,}013\), \(\Delta n=0{,}02\). Natija: \(n=1{,}52\pm0{,}02\)."),
 simtask=[r"\(n\) ni o‘zgartirib, zohiriy qalinlik qanday o‘zgarishini kuzating.", "Apertura (kuzatish burchagi) ortganda zohiriy chuqurlik paraksial formuladan qanday chetlanishini ko‘ring.", "Suv (n = 1,33) qatlami uchun zohiriy chuqurlikni hisoblang."],
 safety=["Obyektivni plastinaga urib yubormang — tubusni pastga faqat okulyardan qaramay, yon tomondan kuzatib tushiring.", "Shisha plastinani qirrasidan ushlang.", "Yoritgich lampasi qiziydi."],
 questions=["Nima uchun hovuz tubi yaqinroq ko‘rinadi?", "Mikrometr vintini bir yo‘nalishda aylantirish nima uchun muhim?", "Maydon chuqurligi o‘lchash aniqligiga qanday ta’sir qiladi?", "Bu usulni suyuqliklar uchun qanday qo‘llash mumkin?", "Ignalar usuli va mikroskop usulini aniqlik bo‘yicha solishtiring."],
 quiz=[
  (r"Haqiqiy qalinlik 6 mm, \(n=1{,}5\). Zohiriy qalinlik:", ["4 mm", "9 mm", "6 mm", "1,5 mm"], 0, r"\(h=d/n\)."),
  (r"\(d=4{,}5\) mm, \(h=3{,}0\) mm. \(n\) =", ["1,5", "0,67", "1,33", "7,5"], 0, r"\(n=d/h\)."),
  (r"Suv ostidagi tosh qanday ko‘rinadi?", ["yaqinroq", "uzoqroq", "haqiqiy joyida", "ko‘rinmaydi"], 0, r"\(h=d/n<d\)."),
  (r"Mikroskopda fokuslash aniqligini nima cheklaydi?", ["maydon chuqurligi", "okulyar rangi", "stol balandligi", "lampa quvvati"], 0, r"\(\Delta z\approx\lambda/\mathrm{NA}^2\)."),
  (r"\(h=d/n\) formulasi qaysi nurlar uchun aniq?", ["paraksial (o‘qqa yaqin)", "chekka", "faqat qizil", "faqat qaytgan"], 0, "Kichik burchak yaqinlashuvi."),
  (r"Mikrometr vintini doim bir tomonga aylantirish qaysi xatolikni yo‘qotadi?", ["lyuft (bo‘shliq) xatoligini", "tasodifiy xatolikni", "parallaksni", "rang xatoligini"], 0, "Mexanik bo‘shliq."),
  (r"Katta aperturali obyektivning afzalligi:", ["maydon chuqurligi kichik — fokuslash aniqroq", "kattalashtirish kichik", "yorug‘lik kam", "fokus uzun"], 0, "Ammo aberratsiya ortadi."),
  (r"Suv qatlami 2 sm. Zohiriy chuqurlik (n=1,33):", ["≈ 1,5 sm", "≈ 2,7 sm", "2 sm", "≈ 1 sm"], 0, r"\(2/1{,}33\)."),
  (r"Nisbiy xatolikda qaysi had odatda ustun?", [r"\(\Delta h/h\)", r"\(\Delta d/d\)", "ikkalasi nol", r"\(\Delta n\)"], 0, "Fokuslash noaniqligi mikrometrdan katta."),
  (r"Zohiriy qalinlikni o‘lchashda mikroskop nimani o‘lchaydi?", ["tubusning vertikal siljishini", "kattalashtirishni", "yorug‘lik kuchini", "sinish burchagini"], 0, "Ikki fokuslash orasidagi siljish.")]),

dict(n=24, sess="L31", sim="lens", tn=["TN8", "TN9", "TN10", "TN14"], refs=[3, 4, "Q6"], intl=["hecht", "pedrotti"],
 title=r"Qavariq va botiq linzalarning bosh fokus masofasini aniqlash. Sferik aberratsiyani kuzatish",
 short=r"Linzalarning fokus masofasi",
 goal=r"Yupqa linza formulasi va Bessel usulida yig‘uvchi linza fokus masofasini, yig‘uvchi linza bilan kombinatsiyada sochuvchi linza fokus masofasini aniqlash; diafragmalar yordamida sferik aberratsiyani kuzatish.",
 equip=["Optik skamya, yoritilgan buyum (strelka yoki harfli diafragma), ekran", "Yig‘uvchi (f ≈ 10–25 sm) va sochuvchi linzalar", "Halqasimon va markaziy diafragmalar (aberratsiya uchun)", "O‘lchov lentasi"],
 theory=[
  ("Yupqa linza formulasi", r"$$\frac1a+\frac1{b}=\frac1f,\qquad D=\frac1f\ \text{(dioptriya)},\qquad \Gamma=\frac{b}{a}.$$<p>\(a\) — buyumgacha, \(b\) — tasvirgacha masofa; sochuvchi linza uchun \(f<0\), mavhum tasvir uchun \(b<0\).</p>"),
  ("Bessel usuli", r"<p>Buyum va ekran orasidagi masofa \(L>4f\) bo‘lsa, linzaning ikki holatida aniq tasvir olinadi (kattalashgan va kichiklashgan). Holatlar orasidagi masofa \(l\) bo‘lsa,</p>$$f=\frac{L^2-l^2}{4L}.$$<p>Bu usulda linza qalinligi va uning optik markazini aniq bilish shart emas — aniqroq.</p>"),
  ("Sochuvchi linza va aberratsiya", r"<p>Sochuvchi linza haqiqiy tasvir bermaydi; uni ma’lum yig‘uvchi linza bilan zich qo‘yib, sistema fokusi \(F\) o‘lchanadi: \(\dfrac1{f_2}=\dfrac1F-\dfrac1{f_1}\). <b>Sferik aberratsiya:</b> linza chetidan o‘tgan nurlar markaziy nurlarga qaraganda yaqinroqda fokuslanadi; halqasimon va markaziy diafragmalar bilan fokuslar farqi o‘lchanadi.</p>")],
 proc=[r"Buyum, linza va ekranni skamyaga qo‘ying; linzani surib, aniq tasvir oling; \(a\), \(b\) ni yozing (3 ta holat).", r"Ekran va buyum orasini \(L\approx4{,}5f\) qilib qo‘ying; linzaning ikki aniq tasvir holatini topib, \(l\) ni o‘lchang (Bessel).", r"Sochuvchi linzani yig‘uvchi bilan zich qo‘yib, sistema fokusini toping va \(f_2\) ni hisoblang.", "Linzaga avval markaziy, so‘ng halqasimon diafragma qo‘yib, aniq tasvir holatlarini solishtiring.", "Natijalarni jadvalga kiritib, usullarni solishtiring."],
 tbl=(["Usul", "a yoki L, sm", "b yoki l, sm", "f, sm", "D, dptr"], 6),
 calc=r"<p>Formula usuli: \(f=ab/(a+b)\), \(\dfrac{\Delta f}{f}=\dfrac{b\Delta a+a\Delta b}{a(a+b)}+\ldots\). Bessel: \(\Delta f=\dfrac{L^2+l^2}{4L^2}\Delta L+\dfrac{l}{2L}\Delta l\). Aberratsiya o‘lchovi: bo‘ylama aberratsiya \(\delta s=b_{markaz}-b_{chet}\).</p>",
 example=(r"1) \(a=30\) sm, \(b=60\) sm. 2) Bessel: \(L=100\) sm, \(l=44{,}7\) sm. 3) Yig‘uvchi \(f_1=10\) sm sochuvchi linza bilan zich qo‘yilganda sistema fokusi \(F=25\) sm. Fokus masofalarini toping.",
  r"1) \(f=30\cdot60/90=20{,}0\) sm, \(D=5\) dptr. 2) \(f=(10^4-1998)/400=20{,}0\) sm. 3) \(1/f_2=1/25-1/10=-0{,}06\) ⇒ \(f_2=-16{,}7\) sm, \(D=-6\) dptr."),
 simtask=[r"Buyumni \(2f\) dan \(f\) ga yaqinlashtiring: tasvir o‘lchami va joyi qanday o‘zgaradi?", r"\(a<f\) bo‘lganda qanday tasvir hosil bo‘ladi?", "Aberratsiyani yoqib, chekka nurlar fokusi markaziy nurlarnikidan qancha farq qilishini o‘lchang."],
 safety=["Linzalarni faqat qirrasidan ushlang, barmoq izi qoldirmang.", "Quyosh nurini linza bilan fokuslamang — kuydirishi mumkin.", "Lampalar qiziydi."],
 questions=["Bessel usulining yupqa linza formulasi usulidan afzalligi nimada?", r"Nima uchun Bessel usulida \(L>4f\) bo‘lishi kerak?", "Sochuvchi linzaning fokus masofasini bevosita o‘lchab bo‘lmasligi sababi?", "Sferik aberratsiyani qanday kamaytirish mumkin?", "Ko‘zoynak linzalarining optik kuchi qanday tanlanadi?"],
 quiz=[
  (r"\(a=40\) sm, \(b=40\) sm. \(f\) =", ["20 sm", "40 sm", "80 sm", "10 sm"], 0, r"\(f=ab/(a+b)\)."),
  (r"Optik kuchi −4 dptr bo‘lgan linza:", ["sochuvchi, f = −25 sm", "yig‘uvchi, f = 25 sm", "yig‘uvchi, f = 4 m", "sochuvchi, f = −4 m"], 0, r"\(f=1/D\)."),
  (r"Bessel usuli formulasi:", [r"\(f=(L^2-l^2)/4L\)", r"\(f=L/4\)", r"\(f=l^2/L\)", r"\(f=(L-l)/2\)"], 0, "Ikki holat orasidagi masofa."),
  (r"Buyum \(2f\) masofada bo‘lsa, tasvir:", ["haqiqiy, teskari, buyumga teng", "mavhum, to‘g‘ri, kattalashgan", "haqiqiy, kichraygan", "hosil bo‘lmaydi"], 0, r"\(b=2f\), \(\Gamma=1\)."),
  (r"Buyum fokus ichida (\(a<f\)) bo‘lsa, yig‘uvchi linza:", ["mavhum, to‘g‘ri, kattalashgan tasvir beradi", "haqiqiy tasvir beradi", "tasvir bermaydi", "kichraygan tasvir beradi"], 0, "Lupa rejimi."),
  (r"Zich qo‘yilgan linzalar sistemasining optik kuchi:", [r"\(D_1+D_2\)", r"\(D_1D_2\)", r"\(D_1-D_2\)", r"\(1/(D_1+D_2)\)"], 0, "Yupqa linzalar."),
  (r"Sferik aberratsiyada chekka nurlar:", ["linzaga yaqinroq fokuslanadi", "uzoqroq fokuslanadi", "fokuslanmaydi", "bir nuqtada fokuslanadi"], 0, "Yig‘uvchi linza uchun."),
  (r"Bessel usulida aniq tasvir ikki holatda olinishi uchun shart:", [r"\(L>4f\)", r"\(L<2f\)", r"\(L=f\)", r"\(L<f\)"], 0, r"\(l^2=L^2-4fL>0\)."),
  (r"Yig‘uvchi linzaning optik kuchi 5 dptr. Fokus masofasi:", ["20 sm", "5 sm", "50 sm", "2 m"], 0, r"\(1/5\) m."),
  (r"Diafragmalash (aperturani kichraytirish) aberratsiyaga qanday ta’sir qiladi?", ["kamaytiradi", "oshiradi", "ta’sir qilmaydi", "yo‘qotadi va yorug‘likni oshiradi"], 0, "Faqat paraksial nurlar qoladi.")]),

dict(n=25, sess="L32", sim="microscope", tn=["TN8", "TN9", "TN10", "TN13"], refs=[3, 4, "Q6"], intl=["hecht", "pedrotti"],
 title=r"Mikroskopning ishlash prinsipi va uning kattalashtirishini aniqlash",
 short=r"Mikroskop kattalashtirishi",
 goal=r"Mikroskopning optik sxemasini o‘rganish; obyekt-mikrometr va yordamchi shkala yordamida mikroskopning kattalashtirishini tajribada aniqlash, uni obyektiv va okulyar fokus masofalaridan hisoblangan qiymat bilan solishtirish; ajrata olish chegarasini baholash.",
 equip=["Biologik mikroskop (almashtiriladigan obyektiv va okulyarlar)", "Obyekt-mikrometr (1 mm 100 bo‘lakka bo‘lingan)", "Millimetrli shkala (25 sm masofaga qo‘yiladi) yoki okulyar-mikrometr", "Yoritgich"],
 theory=[
  ("Optik sxema", r"<p>Obyektiv (\(f_{ob}\) kichik) buyumning kattalashgan haqiqiy teskari tasvirini okulyar fokal tekisligiga yaqin joyda hosil qiladi; okulyar uni lupa kabi yana kattalashtiradi. Umumiy kattalashtirish:</p>$$\Gamma=\Gamma_{ob}\Gamma_{ok}\approx\frac{\Delta}{f_{ob}}\cdot\frac{D}{f_{ok}},$$<p>\(\Delta\) — optik tubus uzunligi (obyektivning orqa fokusi va okulyarning old fokusi orasidagi masofa), \(D=25\) sm — eng yaxshi ko‘rish masofasi.</p>"),
  ("Tajribada aniqlash", r"<p>Bir ko‘z bilan mikroskopdagi obyekt-mikrometr tasviriga, ikkinchi ko‘z bilan 25 sm uzoqlikdagi shkalaga qaraladi. Obyekt-mikrometrning \(n\) bo‘lagi (\(n\cdot0{,}01\) mm) shkalaning \(N\) mm iga to‘g‘ri kelsa, \(\Gamma=N/(n\cdot0{,}01)\).</p>"),
  ("Ajrata olish chegarasi", r"<p>Difraksiya tufayli ikki nuqtani ajrata olish chegarasi \(d_{min}\approx\dfrac{0{,}61\lambda}{\mathrm{NA}}\), \(\mathrm{NA}=n\sin u\) — sonli apertura. Shuning uchun foydali kattalashtirish \(\approx(500\ldots1000)\mathrm{NA}\) dan oshmaydi.</p>")],
 proc=["Mikroskopni yoritib, obyekt-mikrometrni aniq fokuslang.", "25 sm masofaga shkala qo‘yib, ikki ko‘zda bir vaqtda kuzating; tasvirlarni ustma-ust tushiring.", r"Obyekt-mikrometrning \(n\) bo‘lagi shkalaning necha mm iga to‘g‘ri kelishini yozing.", "Boshqa obyektiv/okulyar juftliklari bilan takrorlang.", r"Tajribaviy \(\Gamma\) ni asboblardagi yozuvlar ko‘paytmasi (masalan, 10× · 15×) bilan solishtiring.", "Obyektiv aperturasi bo‘yicha ajrata olish chegarasini hisoblang."],
 tbl=(["Obyektiv × okulyar", "n (bo‘lak)", "N, mm", "Γ tajriba", "Γ nominal"], 4),
 calc=r"<p>\(\Gamma=N/(0{,}01n)\). Xatolik: \(\Delta\Gamma/\Gamma=\Delta N/N+\Delta n/n\) — ko‘proq bo‘lakni qamrab olish xatoni kamaytiradi.</p>",
 example=(r"\(f_{ob}=1{,}0\) sm, \(f_{ok}=2{,}5\) sm, \(\Delta=16\) sm. Kattalashtirishni hisoblang. Tajribada obyekt-mikrometrning 10 bo‘lagi (0,10 mm) 25 sm dagi shkalaning 16 mm iga to‘g‘ri keldi. \(\mathrm{NA}=0{,}25\), \(\lambda=550\) nm da ajrata olish chegarasi?",
  r"\(\Gamma=16\cdot25/(1\cdot2{,}5)=160\). Tajriba: \(\Gamma=16/0{,}10=160\) ✓. \(d_{min}=0{,}61\cdot0{,}55/0{,}25=1{,}3\) mkm."),
 simtask=["Obyektiv fokus masofasini kamaytiring: kattalashtirish qanday o‘zgaradi?", r"Tubus uzunligini o‘zgartirib, \(\Gamma\) ning \(\Delta\) ga proporsionalligini tekshiring.", "Model ekranidagi shkala bo‘yicha kattalashtirishni o‘lchab, hisob bilan solishtiring."],
 safety=["Obyektivni preparatga tegizmang: fokuslashni pastdan yuqoriga qarab bajaring.", "Linzalarni faqat maxsus salfetka bilan arting.", "Ko‘zgu bilan quyosh nurini mikroskopga yo‘naltirmang."],
 questions=["Obyektiv qanday tasvir beradi va okulyar qanday?", "Nima uchun kattalashtirishni cheksiz oshirish ma’nosiz?", "Immersion moy ajrata olish qobiliyatini qanday oshiradi?", "Mikroskop va teleskop sxemalarini solishtiring.", "Maktabda mikroskop bilan ishlashni qanday o‘rgatish kerak?"],
 quiz=[
  (r"Obyektiv 10×, okulyar 15×. Kattalashtirish:", ["150×", "25×", "1,5×", "5×"], 0, "Ko‘paytma."),
  (r"Mikroskop obyektivi beradigan tasvir:", ["haqiqiy, teskari, kattalashgan", "mavhum, to‘g‘ri", "haqiqiy, kichraygan", "mavhum, teskari"], 0, "Buyum fokus va 2f orasida."),
  (r"Eng yaxshi ko‘rish masofasi:", ["25 sm", "10 sm", "1 m", "2,5 sm"], 0, "Normal ko‘z uchun."),
  (r"Ajrata olish chegarasi \(d_{min}\approx\):", [r"\(0{,}61\lambda/\mathrm{NA}\)", r"\(\lambda\cdot\mathrm{NA}\)", r"\(f_{ob}/f_{ok}\)", r"\(\Delta/D\)"], 0, "Reley mezoni."),
  (r"Immersion moy nima uchun ishlatiladi?", ["sonli aperturani oshirish uchun", "linzani tozalash uchun", "yorug‘likni kamaytirish uchun", "fokusni uzaytirish uchun"], 0, r"\(\mathrm{NA}=n\sin u\)."),
  (r"Obyekt-mikrometrning 5 bo‘lagi (0,05 mm) 20 mm ga to‘g‘ri keldi. \(\Gamma\) =", ["400", "100", "40", "250"], 0, r"\(20/0{,}05\)."),
  (r"Okulyar qanday vazifani bajaradi?", ["lupa kabi oraliq tasvirni kattalashtiradi", "buyumni yoritadi", "tasvirni teskari qiladi", "yorug‘likni qutblaydi"], 0, "Mavhum kattalashgan tasvir."),
  (r"Obyektiv fokus masofasi kichraysa, kattalashtirish:", ["ortadi", "kamayadi", "o‘zgarmaydi", "nolga teng"], 0, r"\(\Gamma\propto1/f_{ob}\)."),
  (r"Foydali kattalashtirish chegarasi taxminan:", [r"\((500\ldots1000)\mathrm{NA}\)", "cheksiz", "10×", r"\(1/\mathrm{NA}\)"], 0, "Ko‘z ajrata olishi bilan moslash."),
  (r"Fokuslashda obyektivni preparatga tegizmaslik uchun:", ["yon tomondan qarab pastga tushirib, so‘ng okulyardan qarab yuqoriga ko‘tarish", "faqat okulyardan qarab pastga tushirish", "eng katta obyektivdan boshlash", "yoritgichni o‘chirish"], 0, "Xavfsiz fokuslash qoidasi.")]),

dict(n=26, sess="L33", sim="grating", tn=["TN8", "TN9", "TN6", "TN14", "TN15"], refs=[3, 4, "Q6"], intl=["hecht", "born"],
 title=r"Difraksion panjara yordamida yorug‘likning to‘lqin uzunligini aniqlash",
 short=r"Difraksion panjara",
 goal=r"Difraksion panjara yordamida lazer yoki spektral lampa yorug‘ligining to‘lqin uzunligini aniqlash; difraksiya tartibi, panjara davri va ajrata olish qobiliyati orasidagi bog‘lanishni o‘rganish.",
 equip=["Difraksion panjara (50, 100, 300 shtrix/mm)", "Yarimo‘tkazgichli lazer (650 nm) yoki He-Ne lazer (633 nm), oq yorug‘lik manbai", "Ekran va o‘lchov lentasi (yoki goniometr-spektrometr)", "Optik skamya, ushlagichlar"],
 theory=[
  ("Panjara formulasi", r"<p>Davri \(d\) (1 mm dagi shtrixlar soni \(N_0\) bo‘lsa, \(d=1/N_0\)) bo‘lgan panjarada bosh maksimumlar sharti:</p>$$d\sin\varphi=k\lambda,\qquad k=0,\pm1,\pm2,\ldots$$<p>Ekran panjaradan \(L\) masofada bo‘lsa va \(k\)-tartib maksimum markazdan \(x_k\) uzoqlikda bo‘lsa, \(\operatorname{tg}\varphi=x_k/L\).</p>"),
  ("Maksimal tartib va dispersiya", r"<p>\(k_{max}<d/\lambda\). Burchak dispersiyasi \(D=d\varphi/d\lambda=k/(d\cos\varphi)\) — yuqori tartiblarda spektr kengroq. Oq yorug‘likda markaziy maksimum oq, qolganlari spektr shaklida (binafsha ichkarida, qizil tashqarida).</p>"),
  ("Ajrata olish qobiliyati", r"<p>\(R=\lambda/\delta\lambda=kN\), \(N\) — yoritilgan shtrixlar soni. Natriyning 589,0 va 589,6 nm dubletini ajratish uchun \(R\gtrsim1000\) kerak.</p>")],
 proc=[r"Lazer, panjara va ekranni bir o‘qqa o‘rnating; \(L\) ni o‘lchang (1–2 m).", r"Ekranda ±1, ±2 tartibli dog‘lar orasidagi masofalarni o‘lchang; \(x_k=(x_{+k}+x_{-k})/2\).", r"\(\varphi=\operatorname{arctg}(x_k/L)\) va \(\lambda=d\sin\varphi/k\) ni hisoblang.", "Boshqa davrli panjara bilan takrorlang.", "Oq yorug‘lik bilan spektrni kuzatib, qizil va binafsha chegaralarining to‘lqin uzunliklarini baholang.", "Natijalarni lazerning nominal to‘lqin uzunligi bilan solishtiring."],
 tbl=(["N₀, mm⁻¹", "k", "x_k, sm", "φ, °", "λ, nm"], 6),
 calc=r"<p>\(\lambda=d\sin(\operatorname{arctg}(x_k/L))/k\). Xatolik: \(\dfrac{\Delta\lambda}{\lambda}\approx\cos^2\varphi\left(\dfrac{\Delta x}{x}+\dfrac{\Delta L}{L}\right)+\dfrac{\Delta d}{d}\). Katta \(L\) va yuqori tartib aniqlikni oshiradi.</p>",
 example=(r"Panjara 100 shtrix/mm, \(L=1{,}00\) m, birinchi tartib dog‘lar markazdan 6,35 sm da. \(\lambda\) ni toping. Bu panjarada maksimal tartib qancha?",
  r"\(d=10\) mkm. \(\operatorname{tg}\varphi=0{,}0635\), \(\sin\varphi=0{,}0634\). \(\lambda=10\cdot0{,}0634=0{,}634\) mkm = 634 nm (He-Ne lazer, 632,8 nm). \(k_{max}<10/0{,}634=15{,}8\) ⇒ 15."),
 simtask=["To‘lqin uzunligini 450 nm dan 650 nm ga oshiring: maksimumlar markazdan uzoqlashadimi yoki yaqinlashadimi?", "Panjara davrini kichraytiring (shtrixlarni ko‘paytiring): nima o‘zgaradi?", "Oq yorug‘lik rejimida ikkinchi va uchinchi tartib spektrlari ustma-ust tushishini kuzating."],
 safety=["Lazer nurini ko‘zga, odamlarga va yaltiroq sirtlarga yo‘naltirmang.", "Lazerni stol balandligida, ko‘z sathidan pastda o‘rnating.", "Ekrandagi dog‘ni lazer tomonidan emas, yon tomondan kuzating."],
 questions=["Nima uchun panjarada maksimumlar tor va yorqin?", "Panjara va prizma spektrlari qanday farq qiladi?", "Ajrata olish qobiliyati qanday oshiriladi?", "CD/DVD diskdagi rangli tovlanishni qanday tushuntirasiz?", "Maktabda lazer va panjara bilan qanday xavfsiz namoyish o‘tkazasiz?"],
 quiz=[
  (r"Panjara formulasi:", [r"\(d\sin\varphi=k\lambda\)", r"\(d\cos\varphi=k\lambda\)", r"\(d=k\lambda\sin\varphi\)", r"\(\lambda=kd\)"], 0, "Bosh maksimumlar sharti."),
  (r"500 shtrix/mm panjaraning davri:", ["2 mkm", "0,5 mkm", "5 mkm", "500 mkm"], 0, r"\(1/500\) mm."),
  (r"\(d=2\) mkm, \(\lambda=500\) nm. Maksimal tartib:", ["3", "4", "2", "5"], 0, r"\(k<4\); \(k=4\) da \(\varphi=90^\circ\) — kuzatilmaydi."),
  (r"Qaysi rang birinchi tartibda markazga eng yaqin?", ["binafsha", "qizil", "sariq", "yashil"], 0, r"\(\sin\varphi\propto\lambda\)."),
  (r"Ajrata olish qobiliyati:", [r"\(R=kN\)", r"\(R=d/\lambda\)", r"\(R=N/k\)", r"\(R=\lambda d\)"], 0, "Shtrixlar soni va tartib."),
  (r"\(L=2\) m, \(x_1=13\) sm, \(d=10\) mkm. \(\lambda\) taxminan:", ["650 nm", "1300 nm", "325 nm", "500 nm"], 0, r"\(\sin\varphi\approx0{,}065\)."),
  (r"Oq yorug‘likda markaziy maksimum:", ["oq rangda", "qizil", "binafsha", "qorong‘i"], 0, r"Barcha to‘lqinlar uchun \(k=0\) da \(\varphi=0\)."),
  (r"Panjara davri kamaysa, maksimumlar orasidagi masofa:", ["ortadi", "kamayadi", "o‘zgarmaydi", "nolga teng"], 0, r"\(\sin\varphi=k\lambda/d\)."),
  (r"Natriy dubleti (589,0 va 589,6 nm) ni 1-tartibda ajratish uchun kamida nechta shtrix kerak?", ["≈ 1000", "≈ 10", "≈ 100 000", "≈ 2"], 0, r"\(R=589/0{,}6\approx980\)."),
  (r"Panjaradan ekrangacha masofani oshirish:", ["o‘lchash aniqligini oshiradi", "to‘lqin uzunligini o‘zgartiradi", "tartiblar sonini kamaytiradi", "maksimumlarni yo‘qotadi"], 0, r"\(x_k\) kattalashadi, nisbiy xatolik kamayadi.")]),

dict(n=27, sess="L34", sim="slits", tn=["TN8", "TN9", "TN5", "TN14"], refs=[3, 4, "Q6"], intl=["hecht", "pedrotti"],
 title=r"Qo‘sh tirqishda va ko‘p sonli tirqishda difraksiya — videokamera vositasida qayd qilish va hisoblash",
 short=r"Qo‘sh va ko‘p tirqishda difraksiya",
 goal=r"Lazer nurining bitta, ikkita va ko‘p tirqishdan o‘tishida hosil bo‘ladigan difraksion manzarani videokamera (veb-kamera, smartfon) bilan qayd qilish, intensivlik profilini kompyuterda tahlil qilib, tirqish kengligi va tirqishlar orasidagi masofani aniqlash.",
 equip=["Lazer (650 nm yoki 532 nm)", "Tirqishlar to‘plami: bitta (b = 0,04–0,16 mm), qo‘sh (d = 0,25–0,5 mm), 3–5 tirqishli slaydlar", "Ekran yoki bevosita kamera sensori; veb-kamera yoki smartfon", "Tahlil dasturi: Tracker, ImageJ yoki Python (tasvir intensivligi profili)"],
 theory=[
  ("Bitta tirqish", r"<p>Kengligi \(b\) bo‘lgan tirqishda minimumlar sharti \(b\sin\theta=m\lambda\) (\(m=\pm1,\pm2,\ldots\)). Intensivlik: \(I=I_0\left(\dfrac{\sin\beta}{\beta}\right)^2\), \(\beta=\dfrac{\pi b\sin\theta}{\lambda}\).</p>"),
  ("N ta tirqish", r"<p>Davri \(d\) bo‘lgan \(N\) ta tirqish uchun:</p>$$I(\theta)=I_0\left(\frac{\sin\beta}{\beta}\right)^2\left(\frac{\sin N\gamma}{\sin\gamma}\right)^2,\qquad \gamma=\frac{\pi d\sin\theta}{\lambda}.$$<p>Bosh maksimumlar \(d\sin\theta=k\lambda\) da; ular orasida \(N-1\) ta minimum va \(N-2\) ta kichik maksimum bor. Qo‘sh tirqishda polosalar oralig‘i \(\Delta x=\lambda L/d\); bitta tirqish difraksiyasi esa manzarani “qobiq” (o‘ram) bilan modulyatsiya qiladi. \(d/b\) butun son bo‘lsa, ba’zi tartiblar yo‘qoladi.</p>"),
  ("Kamera bilan qayd qilish", r"<p>Kamera kuchaytirishi (gain) va ekspozitsiyasi qo‘lda o‘rnatiladi, avtomatika o‘chiriladi — aks holda intensivlik chiziqli bo‘lmaydi. Piksel o‘lchamini ma’lum shkala (millimetrli qog‘oz) suratidan kalibrlash kerak.</p>")],
 proc=[r"Lazer, tirqish va ekranni o‘rnating; \(L\) ni o‘lchang.", "Kamerani ekranga perpendikulyar mahkamlab, millimetrli shkala bilan kalibrlang (mm/piksel).", "Bitta, qo‘sh va ko‘p tirqish manzaralarini bir xil ekspozitsiyada suratga oling.", "Tahlil dasturida markazdan o‘tuvchi chiziq bo‘yicha intensivlik profilini oling.", r"Qo‘sh tirqishda polosalar oralig‘idan \(d\) ni, o‘ram minimumlaridan \(b\) ni hisoblang.", r"Profilni nazariy formula bilan solishtiring; \(N\) ortganda maksimumlar torayishini tahlil qiling."],
 tbl=(["Slayd", "Δx yoki x_min, mm", "L, m", "d yoki b, mm", "Nominal, mm"], 5),
 calc=r"<p>\(d=\lambda L/\Delta x\), \(b=m\lambda L/x_m\). Ko‘p polosalarni qamrab olib o‘rtachalang: \(\Delta x=(x_{n}-x_{1})/(n-1)\). Xatolik: \(\Delta d/d=\Delta(\Delta x)/\Delta x+\Delta L/L\).</p>",
 example=(r"Qo‘sh tirqish: \(d=0{,}25\) mm, \(b=0{,}05\) mm, \(\lambda=650\) nm, \(L=2{,}0\) m. Polosalar oralig‘i, markaziy o‘ram kengligi va undagi yorqin polosalar soni?",
  r"\(\Delta x=650\cdot10^{-9}\cdot2/0{,}25\cdot10^{-3}=5{,}2\) mm. O‘ramning birinchi minimumi \(x=\lambda L/b=26\) mm, markaziy o‘ram kengligi 52 mm. \(d/b=5\) — 5-tartib maksimumi o‘ram minimumiga tushib yo‘qoladi, demak markaziy o‘ramda \(2\cdot4+1=9\) ta yorqin polosa."),
 simtask=[r"\(N\) ni 2 dan 6 ga oshiring: bosh maksimumlar kengligi va ular orasidagi kichik maksimumlar soni qanday o‘zgaradi?", r"Tirqish kengligi \(b\) ni oshiring: o‘ram qanday torayadi?", r"\(d/b=4\) qilib, qaysi tartiblar yo‘qolishini tekshiring."],
 safety=["Lazer nurini kameraga bevosita, katta quvvatda yo‘naltirmang — sensor shikastlanadi (ekrandan suratga oling yoki susaytiruvchi filtr qo‘ying).", "Lazer nurini ko‘zga yo‘naltirmang.", "Qorong‘i xonada simlarni tartibli joylashtiring."],
 questions=["Qo‘sh tirqish manzarasidagi “o‘ram” nimadan kelib chiqadi?", "Tirqishlar soni ortganda maksimumlar nima uchun torayadi?", "Kamera avtomatikasini nima uchun o‘chirish kerak?", "Yung tajribasining fizika tarixidagi ahamiyati nima?", "Maktabda qo‘sh tirqish tajribasini qanday oddiy vositalar bilan ko‘rsatish mumkin?"],
 quiz=[
  (r"Qo‘sh tirqishda polosalar oralig‘i:", [r"\(\lambda L/d\)", r"\(d L/\lambda\)", r"\(\lambda d/L\)", r"\(L/\lambda d\)"], 0, "Kichik burchak yaqinlashuvi."),
  (r"Bitta tirqishda birinchi minimum sharti:", [r"\(b\sin\theta=\lambda\)", r"\(b\sin\theta=\lambda/2\)", r"\(d\sin\theta=\lambda\)", r"\(b=\lambda\)"], 0, "Tirqish ikki yarmidan kelgan to‘lqinlar so‘nadi."),
  (r"\(N=5\) tirqishda ikki bosh maksimum orasidagi minimumlar soni:", ["4", "5", "3", "6"], 0, r"\(N-1\)."),
  (r"\(d\) 2 marta oshsa, polosalar oralig‘i:", ["2 marta kamayadi", "2 marta ortadi", "o‘zgarmaydi", "4 marta kamayadi"], 0, r"\(\Delta x\propto1/d\)."),
  (r"\(d/b=3\) bo‘lsa, qaysi tartib yo‘qoladi?", ["3-tartib", "1-tartib", "2-tartib", "hech biri"], 0, "Bosh maksimum o‘ram minimumiga tushadi."),
  (r"\(\lambda=532\) nm, \(L=1\) m, \(d=0{,}5\) mm. Polosalar oralig‘i:", ["≈ 1,06 mm", "≈ 10,6 mm", "≈ 0,27 mm", "≈ 2,7 mm"], 0, r"\(532\cdot10^{-9}/5\cdot10^{-4}\) m."),
  (r"Tirqishlar soni ortganda bosh maksimumlar:", ["torayadi va yorqinlashadi", "kengayadi", "yo‘qoladi", "o‘zgarmaydi"], 0, r"\(I_{max}\propto N^2\), kengligi \(\propto1/N\)."),
  (r"Kamera intensivlik profili chiziqli bo‘lishi uchun:", ["avto-ekspozitsiya va gain o‘chiriladi", "chaqnoq yoqiladi", "rangli rejim tanlanadi", "fokus avtomatik qilinadi"], 0, "Doimiy sezgirlik kerak."),
  (r"Bitta tirqish kengligi kamaysa, markaziy maksimum:", ["kengayadi", "torayadi", "yo‘qoladi", "o‘zgarmaydi"], 0, r"\(\theta_1\approx\lambda/b\)."),
  (r"Yung tajribasi nimani isbotlagan?", ["yorug‘likning to‘lqin tabiatini", "yorug‘lik tezligini", "fotoeffektni", "qutblanishni"], 0, "1801–1803-yillar.")]),
